  {
    "question": "Which of the following data structures is classified as non‑linear?",
    "options": {
      "A": "Array",
      "B": "Stack",
      "C": "Graph",
      "D": "Queue"
    },
    "correct_answer": "C",
    "explanation": "Graphs represent relationships between elements that are not confined to a single sequential order, making them non‑linear. Arrays, stacks, and queues are all linear structures because their elements can be arranged in a straight line.",
    "difficulty": "Medium"
  },
  {
    "question": "In the context of abstract data types (ADTs), which statement correctly describes the distinction between an ADT and its concrete implementation?",
    "options": {
      "A": "An ADT specifies the operations and their behavior, while a concrete implementation provides the actual code and memory layout.",
      "B": "An ADT includes the programming language syntax, whereas a concrete implementation does not.",
      "C": "An ADT is always faster than its concrete implementation because it is theoretical.",
      "D": "A concrete implementation can be used without defining an ADT first."
    },
    "correct_answer": "A",
    "explanation": "An ADT defines what operations are available and what they should accomplish, independent of how they are realized. The concrete implementation fills in the details such as data layout and algorithmic steps.",
    "difficulty": "Medium"
  },
  {
    "question": "Which data structure typically requires allocating memory for each element at run time rather than at compile time?",
    "options": {
      "A": "Static array",
      "B": "Linked list",
      "C": "Hash table with open addressing",
      "D": "Fixed‑size circular queue"
    },
    "correct_answer": "B",
    "explanation": "A linked list creates a new node for each element using dynamic memory allocation (e.g., malloc or new) when the element is inserted, unlike static arrays or fixed‑size structures that reserve memory beforehand.",
    "difficulty": "Medium"
  },
  {
    "question": "For which data structure is the average‑case time complexity of searching an element O(log n) when the structure is balanced?",
    "options": {
      "A": "Unsorted array",
      "B": "Balanced binary search tree",
      "C": "Singly linked list",
      "D": "Stack"
    },
    "correct_answer": "B",
    "explanation": "In a balanced binary search tree, each comparison eliminates roughly half of the remaining nodes, leading to logarithmic search time on average. The other structures require linear time for search in the average case.",
    "difficulty": "Medium"
  },
  {
    "question": "Which data structure naturally models the behavior of recursive function calls?",
    "options": {
      "A": "Queue",
      "B": "Stack",
      "C": "Binary tree",
      "D": "Graph"
    },
    "correct_answer": "B",
    "explanation": "A stack follows last‑in‑first‑out (LIFO) order, exactly mirroring how recursive calls are pushed onto and popped from the call stack during execution.",
    "difficulty": "Medium"
  }
]
